#include "window.h"
#include "messagemodel.h"
#include <QtWidgets>
#include <QSettings>
#include <iostream>
#include <source_location>
struct QuietVoice:SpeechBackend{void configure(const SpeechSettings&)override{}void speak(const QString&,const std::atomic_bool&)override{}};
struct IntegrationChecks{
 static void require(bool b,std::source_location l=std::source_location::current()){if(!b)throw std::runtime_error("presentation line "+std::to_string(l.line()));}
 static void run(){QTemporaryDir folder;QString output=qEnvironmentVariable("POCSAG_QA_DIR");if(!output.isEmpty())QDir().mkpath(output);{
 Window w(folder.path(),std::make_unique<QuietVoice>());w.generalCopy_->setChecked(false);require(w.glacier_&&w.textSize_==1);w.sql("INSERT INTO capcodes(ric,alias,color,active,show_bottom) VALUES(42,'R-MED1','#15803D',1,1),(43,'R-MED2','#1769AA',1,1)");for(int i=0;i<40;++i)w.received({uint(i%3==0?99:i%2==0?42:43),0,2400,"ALPHA",("Message synthétique de validation graphique — ligne "+std::to_string(i)+". Texte long consultable intégralement par double-clic, sans modification du message."),0},169626000,"test",QDateTime::fromString("2026-11-05T15:23:01Z",Qt::ISODate));w.show();QApplication::processEvents();require(w.all_->rowCount()==40&&w.saved_->rowCount()==26);require(w.all_->index(0,8).data(Qt::ForegroundRole).value<QColor>()==QColor("#172C3E"));require(w.saved_->index(0,6).data().toString().startsWith("R-MED"));
 for(QSize size:{QSize(1366,768),QSize(1600,900),QSize(1920,1080),QSize(2560,1440)}){w.resize(QSize(qRound(size.width()/w.devicePixelRatioF()),qRound(size.height()/w.devicePixelRatioF())));QApplication::processEvents();w.allView_->scrollToBottom();w.savedView_->scrollToBottom();QApplication::processEvents();std::cout<<"window="<<w.width()<<"x"<<w.height()<<" tables="<<w.allView_->height()<<","<<w.savedView_->height()<<" frequency="<<w.frequencyDisplay_->isVisible()<<","<<w.frequencyDisplay_->width()<<","<<w.frequencyDisplay_->mapTo(&w,QPoint(0,0)).x()<<std::endl;if(!output.isEmpty())w.grab().save(output+QString("/glacier-%1x%2.png").arg(size.width()).arg(size.height()));require(w.allView_->height()>=100&&w.savedView_->height()>=100);require(w.frequencyDisplay_->isVisible()&&w.frequencyDisplay_->width()>200);require(w.frequencyDisplay_->mapTo(&w,QPoint(0,0)).x()+w.frequencyDisplay_->width()<=w.width());if(!output.isEmpty())w.grab().save(output+QString("/glacier-%1x%2.png").arg(size.width()).arg(size.height()));}
 w.resize(1600,900);QApplication::processEvents();for(int n=0;n<3;++n){w.findChild<QAction*>("textSize"+QString::number(n))->trigger();std::cout<<"font="<<n<<" size="<<w.textSize_<<" row="<<w.allView_->verticalHeader()->defaultSectionSize()<<std::endl;require(w.textSize_==n&&w.allView_->verticalHeader()->defaultSectionSize()==(n==0?24:n==1?29:34));}w.findChild<QAction*>("textSize1")->trigger();w.findChild<QAction*>("themeDark")->trigger();require(!w.glacier_&&!static_cast<MessageModel*>(w.all_)->glacier);if(!output.isEmpty())w.grab().save(output+"/dark.png");w.findChild<QAction*>("themeGlacier")->trigger();w.tabs_->setCurrentIndex(1);QApplication::processEvents();if(!output.isEmpty())w.grab().save(output+"/spectrum.png");w.tabs_->setCurrentIndex(0);
 auto capture=[&](QString name,auto open){QTimer::singleShot(250,&w,[&,name]{auto dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());require(dialog);if(!output.isEmpty())dialog->grab().save(output+"/"+name+".png");dialog->reject();});open();};capture("capcodes",[&]{w.capcodes();});capture("journals",[&]{w.journal();});capture("speech",[&]{w.speechOptions();});capture("pager",[&]{w.pagerOptions();});capture("profiles",[&]{w.txtProfiles();});capture("receiver",[&]{w.receiverOptions();});capture("message-details",[&]{w.allView_->doubleClicked(w.all_->index(0,8));});capture("warning",[&]{QMessageBox::warning(&w,"Erreur synthétique de validation","Exemple de diagnostic lisible. Aucun fichier utilisateur modifié.");});w.updatePresentationState();require(w.presentationState_->text().contains("WAV : OFF"));w.findChild<QAction*>("themeDark")->trigger();w.findChild<QAction*>("textSize2")->trigger();w.storePreferences();}
 {Window restored(folder.path(),std::make_unique<QuietVoice>());require(!restored.glacier_&&restored.textSize_==2&&restored.all_->rowCount()==40);restored.findChild<QAction*>("themeGlacier")->trigger();require(restored.glacier_);}
 }
};
int main(int argc,char** argv){QApplication app(argc,argv);app.setOrganizationName("POCSAG-Presentation-Tests");app.setApplicationName("Glacier");try{IntegrationChecks::run();std::cout<<"PASS palettes, four client sizes, fonts, aliases, dialogs, persisted theme and SQLite preservation\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
